/**
 * All file content generated by `init` lives here, separated from the
 * command logic. Deliberately compiled-in rather than shipped as template
 * files: no runtime path resolution, nothing to forget in "files",
 * works identically under npm, npx, yarn portal and PnP.
 */

export const PACKAGED_SKILL_PATH =
  "node_modules/@betomorrow/sync-wording/skills/sync-wording/SKILL.md";

/** Section appended to AGENTS.md / CLAUDE.md. A lazy pointer, not an
 * @-import: the skill is read on demand, never inlined in every session. */
export const WORDING_SECTION = `
## Wording (i18n)

Wording sync is handled by @betomorrow/sync-wording.
For any translation/wording task, read ${PACKAGED_SKILL_PATH} first.
`;

export const AGENTS_MD_CREATE = `# Project guide for AI agents
${WORDING_SECTION}`;

export const COPILOT_LINE = `For wording/i18n sync tasks, follow the guide in ${PACKAGED_SKILL_PATH}
`;
